css:
/* Flat One Dark surfaces. Typography overrides target actual UI text. */
:root {
  --font-sans: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
body,
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]),
[data-slot="button"],
[data-slot="input"],
[data-slot="select-trigger"] {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
  font-kerning: normal;
}
:is([data-slot="sidebar"], [data-chat-header], .messages-timeline-scroll, [data-user-message-bubble], .chat-markdown, [data-slot="composer-host"], .composer-tiptap, [data-thread-details-card], [data-settings-page-scroll], [data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="tooltip-popup"]) :where(p, span, a, button, input, textarea, div, label, h1, h2, h3, h4, h5, h6, li, td, th, summary, time):not(:where(code *, pre *, kbd *, samp *, .chat-markdown-codeblock, .chat-markdown-codeblock *, [data-thread-terminal-drawer], [data-thread-terminal-drawer] *)) {
  font-family: "Avenir Next", Avenir, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
}
.chat-markdown,
[data-user-message-bubble],
.composer-tiptap {
  font-size: 1rem;
  line-height: 1.65;
  letter-spacing: normal;
}
.chat-markdown :is(h1, h2, h3, h4, h5, h6) {
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.02em;
  text-wrap: balance;
}
.chat-markdown :is(strong, b) {
  font-weight: 600;
}
[data-chat-header], [data-thread-item] {
  letter-spacing: -0.01em;
}
:is(code, pre, kbd, samp, .chat-markdown-codeblock),
:is(code, pre, kbd, samp, .chat-markdown-codeblock) * {
  font-family: var(--font-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace) !important;
  letter-spacing: normal;
}


/* Midnight Koi · PS25JBC6 · dark observatory glass */
.dark [data-workspace-area="conversation"],
.dark [data-chat-composer-overlay="true"].items-center {
  background: linear-gradient(90deg,#10101a12,#10101a49 38%,#10101a39 65%,#10101a12), var(--theme-background-image) center / contain no-repeat, radial-gradient(ellipse 62% 76% at 93% 4%, #7052a66b 0%, #4b337d44 34%, transparent 76%), radial-gradient(ellipse 61% 66% at 4% 106%, #673c736f 0%, #44265355 37%, transparent 78%), radial-gradient(ellipse 80% 74% at 99% 89%, #394c8c38 0%, transparent 70%), linear-gradient(145deg, #090913 4%, #18142a 50%, #0b0c1b 100%) !important;
}
.dark .messages-timeline-scroll { background: transparent !important; }
/* Solid window surfaces */
.dark [data-slot="sidebar"] {
  background: #151521 !important;
  border-right: 1px solid #343045 !important;
}
.dark [data-slot="sidebar-inner"] {
  background: #151521 !important;
}
.dark [data-slot="sidebar"] .drag-region:has(a[aria-label="T3 Code home"]) {
  background: #1d1b2b !important;
  box-shadow: inset 0 -1px #393449, inset 0 1px #ffffff09;
}
.dark [data-slot="sidebar"] a[aria-label="T3 Code home"] {
  color: #f0e9f8 !important;
}
.dark [data-slot="sidebar-footer"] {
  box-shadow: inset 0 1px #393449;
}
.dark [data-chat-header] {
  background: #191826 !important;
  border-bottom: 1px solid #3b354b !important;
  box-shadow: 0 3px 12px #08071069, inset 0 1px #ffffff09;
  backdrop-filter: none;
}
.dark [data-slot="sidebar"] [data-sidebar-row][aria-current]:not([aria-current="false"]) {
  background: #282439 !important;
  box-shadow: inset 0 0 0 1px #534766, 0 2px 6px #0807104d;
}
.dark [data-slot="sidebar"] [data-sidebar-row][aria-current]:not([aria-current="false"]):hover {
  background: #2e293f !important;
}
.dark [data-slot="sidebar"] [data-sidebar-row]:focus-visible {
  outline: 1px solid #c2aff0;
  outline-offset: -2px;
}
.dark [data-thread-details-card] {
  background: linear-gradient(140deg,#30273fe8,#1c1929ee) !important;
  border: 1px solid #ae9bc345 !important;
  box-shadow: 0 12px 35px #08061245, inset 0 1px #e7d7fc11;
  backdrop-filter: blur(18px) saturate(115%);
}
.dark [data-slot="composer-host"] {
  background: linear-gradient(135deg,#2b263ceb,#1c192af2) !important;
  border: 1px solid #b9a4ce45 !important;
  box-shadow: 0 12px 32px #07061145, inset 0 1px #eadffa14;
  backdrop-filter: blur(18px) saturate(110%);
}
.dark [data-user-message-bubble] {
  background: #30273ee8 !important;
  border: 1px solid #a088b726;
  backdrop-filter: blur(12px);
}
.dark .chat-markdown-codeblock { background: #12111cf5 !important; }
.dark :is([data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]) {
  background: #211e2ff5 !important;
  border-color: #85719d4d !important;
  backdrop-filter: blur(18px);
}
.dark .composer-tiptap [data-placeholder]::before,
.dark .composer-tiptap::before { color: #c3b9d0 !important; }
.dark [data-thread-item] { border-radius: 10px; }
.dark ::selection { background: #826ba877; color: #f2eafa; }
.dark ::-webkit-scrollbar-thumb { background: #73638580; border-radius: 8px; }
.dark ::-webkit-scrollbar-thumb:hover { background: #9682afaa; }
@media (prefers-reduced-motion: reduce) {
  .dark [data-workspace-area="conversation"],
.dark [data-chat-composer-overlay="true"].items-center {
    background-image: radial-gradient(ellipse 62% 76% at 93% 4%, #7052a66b 0%, #4b337d44 34%, transparent 76%), radial-gradient(ellipse 61% 66% at 4% 106%, #673c736f 0%, #44265355 37%, transparent 78%), radial-gradient(ellipse 80% 74% at 99% 89%, #394c8c38 0%, transparent 70%), linear-gradient(145deg, #090913 4%, #18142a 50%, #0b0c1b 100%) !important;
  }
}

/* Accessible destructive button fill; preserve global error indicators and disabled opacity. */
.dark [data-slot="button"][class~="bg-destructive"] {
  --destructive: #a34250;
}
